#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel merge sort using OpenMP tasks
    // Uses squared magnitude to avoid sqrt (ordering is identical).
    auto mag2 = [](const std::complex<double>& z) -> double {
        const double re = z.real();
        const double im = z.imag();
        return re * re + im * im;
    };

    // Comparator with deterministic tie-breakers to avoid non-deterministic ordering
    // when magnitudes are equal (important for reproducibility across thread counts).
    auto comp = [&](const std::complex<double>& a, const std::complex<double>& b) -> bool {
        const double am = mag2(a);
        const double bm = mag2(b);
        if (am < bm) return true;
        if (am > bm) return false;
        // Tie-breakers: real then imag
        if (a.real() < b.real()) return true;
        if (a.real() > b.real()) return false;
        return a.imag() < b.imag();
    };

    std::vector<std::complex<double>> tmp(n);

    // Control task granularity to reduce overhead.
    // A few thousand elements is typically a good cutoff.
    const std::size_t GRAIN = 4096;

    // Recursive task-based mergesort.
    // Sorts src[lo:hi) into dst[lo:hi).
    struct Sorter {
        decltype(comp)& comp;
        const std::size_t GRAIN;

        void mergesort(const std::complex<double>* src,
                       std::complex<double>* dst,
                       std::size_t lo,
                       std::size_t hi) {
            const std::size_t len = hi - lo;
            if (len <= 1) {
                if (len == 1) dst[lo] = src[lo];
                return;
            }

            // For small ranges, do a local stable sort.
            if (len <= GRAIN) {
                // Copy then sort in-place in dst
                std::copy(src + lo, src + hi, dst + lo);
                std::stable_sort(dst + lo, dst + hi, comp);
                return;
            }

            const std::size_t mid = lo + len / 2;

            // Recurse, swapping roles of src/dst so merges read from dst and write to src,
            // then we merge back into dst. This avoids extra allocations.
            #pragma omp task shared(src, dst) firstprivate(lo, mid)
            mergesort(dst, const_cast<std::complex<double>*>(src), lo, mid);

            #pragma omp task shared(src, dst) firstprivate(mid, hi)
            mergesort(dst, const_cast<std::complex<double>*>(src), mid, hi);

            #pragma omp taskwait

            // Merge from src (which now holds sorted halves) into dst.
            std::size_t i = lo, j = mid, k = lo;
            while (i < mid && j < hi) {
                if (comp(src[i], src[j])) dst[k++] = src[i++];
                else                       dst[k++] = src[j++];
            }
            while (i < mid) dst[k++] = src[i++];
            while (j < hi)  dst[k++] = src[j++];
        }
    };

    // Initialize tmp with input so the first recursive level has valid "dst" content.
    // We will call mergesort(tmp -> x) by swapping pointers in the recursion.
    std::copy(x.begin(), x.end(), tmp.begin());

    Sorter sorter{comp, GRAIN};

    #pragma omp parallel
    {
        #pragma omp single nowait
        {
            // Sort tmp into x
            sorter.mergesort(tmp.data(), x.data(), 0, n);
        }
    }
}
